from jsonb_to_recordset($q$[{"id":7039,"materia":"trib","nivel":0,"enunciado":"O imposto pago anualmente por quem tem carro é o:","opcoes":["IPVA","IPTU","ISS","ITR"],"explicacao":"É de competência dos estados."},{"id":7040,"materia":"trib","nivel":0,"enunciado":"O Imposto de Renda é um tributo:","opcoes":["Federal","Estadual","Municipal","Internacional"],"explicacao":"Art. 153, III, da Constituição."},{"id":7041,"materia":"trib","nivel":1,"enunciado":"São espécies tributárias, segundo o STF:","opcoes":["Impostos, taxas, contribuições, empréstimos compulsórios e de melhoria","Só impostos e taxas, sem nenhuma outra espécie tributária","Impostos, multas, juros e correção monetária","Tarifas, preços e pedágios"],"explicacao":"É a teoria pentapartida."},{"id":7042,"materia":"trib","nivel":1,"enunciado":"Pela anterioridade anual, a lei que cria ou aumenta tributo só pode cobrá-lo:","opcoes":["No exercício seguinte ao da publicação","No mesmo dia da publicação da lei","Depois de 5 anos de vigência da lei","Só com plebiscito"],"explicacao":"Art. 150, III, b, da Constituição."},{"id":7043,"materia":"trib","nivel":2,"enunciado":"Pela noventena, o tributo criado ou aumentado só pode ser cobrado depois de:","opcoes":["90 dias da publicação da lei","30 dias da publicação da lei","1 ano completo da publicação","180 dias"],"explicacao":"Art. 150, III, c, da Constituição."},{"id":7044,"materia":"trib","nivel":2,"enunciado":"Pela imunidade recíproca, União, estados e municípios não podem cobrar entre si impostos sobre:","opcoes":["Patrimônio, renda e serviços","Qualquer taxa","Contribuições de melhoria","Multas de trânsito"],"explicacao":"Art. 150, VI, a, da Constituição."},{"id":7045,"materia":"trib","nivel":2,"enunciado":"Emitir nota fiscal e entregar declarações são exemplos de obrigação tributária:","opcoes":["Acessória","Principal","Moral","Contratual"],"explicacao":"A principal é pagar o tributo ou a multa."},{"id":7046,"materia":"trib","nivel":2,"enunciado":"Pelo CTN, o fisco tem, em regra, quantos anos para constituir o crédito tributário (decadência)?","opcoes":["5 anos","2 anos","10 anos","20 anos"],"explicacao":"Art. 173 do CTN."},{"id":7047,"materia":"trib","nivel":3,"enunciado":"Pelo CTN, são hipóteses de exclusão do crédito tributário:","opcoes":["Isenção e anistia","Pagamento e compensação","Moratória e parcelamento","Prescrição e decadência"],"explicacao":"Art. 175 do CTN."},{"id":7048,"materia":"trib","nivel":4,"enunciado":"Pela EC 132/2023, o Imposto Seletivo incide sobre:","opcoes":["Bens e serviços prejudiciais à saúde ou ao ambiente","Todos os alimentos da cesta básica nacional, sem exceção","Livros, jornais e periódicos","Exportações"],"explicacao":"É o chamado \"imposto do pecado\"."},{"id":7049,"materia":"afo","nivel":0,"enunciado":"A Lei Orçamentária Anual (LOA):","opcoes":["Estima a receita e fixa a despesa do ano","Define o plano de governo para 10 anos","Cria tributos novos para o ano seguinte","Julga as contas do governo"],"explicacao":"Art. 165, § 8º, da Constituição."},{"id":7050,"materia":"afo","nivel":3,"enunciado":"Pela Lei de Responsabilidade Fiscal, a despesa com pessoal dos estados não pode passar de:","opcoes":["60% da receita corrente líquida","50% da receita corrente líquida","40% da receita corrente líquida","80% da receita corrente líquida"],"explicacao":"Na União, o limite é 50%."},{"id":7051,"materia":"afo","nivel":4,"enunciado":"A LRF proíbe ato que aumente despesa com pessoal nos últimos quantos dias do mandato?","opcoes":["180 dias","90 dias","30 dias","1 ano"],"explicacao":"Art. 21 da LRF."},{"id":7052,"materia":"afo","nivel":2,"enunciado":"Os créditos da Fazenda vencidos e não pagos, inscritos para cobrança, formam a:","opcoes":["Dívida ativa","Dívida flutuante","Receita de capital","Reserva de contingência"],"explicacao":"Art. 39 da Lei 4.320/1964."},{"id":7053,"materia":"cont","nivel":0,"enunciado":"Os estoques de mercadorias de uma loja ficam no:","opcoes":["Ativo circulante","Passivo circulante","Patrimônio líquido","Passivo não circulante"],"explicacao":"Serão vendidos no curto prazo."},{"id":7054,"materia":"cont","nivel":1,"enunciado":"A depreciação se aplica a bens do imobilizado como:","opcoes":["Máquinas, veículos e móveis","Terrenos sem construção","Dinheiro em caixa e em bancos","Estoques"],"explicacao":"Registra o desgaste pelo uso ou pelo tempo."},{"id":7055,"materia":"cont","nivel":2,"enunciado":"Terrenos sofrem depreciação?","opcoes":["Não, em regra, pois não se desgastam com o uso","Sim, à taxa de 10% ao ano, como as máquinas","Sim, à taxa de 4% ao ano, como os prédios","Só se forem urbanos"],"explicacao":"Os prédios sobre eles, sim."},{"id":7056,"materia":"cont","nivel":3,"enunciado":"A amortização se aplica a:","opcoes":["Intangíveis com vida útil definida","Terrenos e edificações","Recursos minerais e florestais","Estoques"],"explicacao":"Exemplo: direito de uso por prazo determinado."},{"id":7057,"materia":"cont","nivel":2,"enunciado":"Com vendas de R$ 100 mil e custo das mercadorias vendidas de R$ 60 mil, o lucro bruto é:","opcoes":["R$ 40 mil","R$ 160 mil","R$ 60 mil","R$ 100 mil"],"explicacao":"Vendas − CMV."},{"id":7058,"materia":"cont","nivel":3,"enunciado":"Estoque inicial R$ 10 mil, compras R$ 50 mil e estoque final R$ 15 mil. O CMV é:","opcoes":["R$ 45 mil","R$ 75 mil","R$ 55 mil","R$ 35 mil"],"explicacao":"CMV = EI + compras − EF."},{"id":7059,"materia":"cont","nivel":4,"enunciado":"Uma máquina de R$ 50 mil, com valor residual de R$ 10 mil e vida útil de 8 anos, tem depreciação linear anual de:","opcoes":["R$ 5 mil","R$ 6,25 mil","R$ 4 mil","R$ 10 mil"],"explicacao":"(50 − 10) ÷ 8."},{"id":7060,"materia":"cont","nivel":1,"enunciado":"Pelo regime de competência, receitas e despesas são registradas:","opcoes":["No período em que ocorrem, pagas ou não","Só quando o dinheiro entra ou sai","No fim do ano, todas juntas","Quando o auditor pede"],"explicacao":"É o regime exigido pela contabilidade societária."},{"id":7061,"materia":"adua","nivel":0,"enunciado":"O Imposto de Importação é de competência:","opcoes":["Da União","Dos estados","Dos municípios","Do Mercosul"],"explicacao":"Art. 153, I, da Constituição."},{"id":7062,"materia":"adua","nivel":0,"enunciado":"O órgão que controla a entrada e a saída de mercadorias do país é a:","opcoes":["Receita Federal","Polícia Militar","Anvisa, sozinha","Prefeitura"],"explicacao":"Por meio da fiscalização aduaneira."},{"id":7063,"materia":"adua","nivel":1,"enunciado":"A diferença entre contrabando e descaminho é que, no contrabando, a mercadoria:","opcoes":["É proibida","É permitida, mas sem pagar tributos","É de baixo valor","Vem pelo correio"],"explicacao":"No descaminho, a mercadoria é permitida, mas o imposto é sonegado."},{"id":7064,"materia":"adua","nivel":2,"enunciado":"O Siscomex é:","opcoes":["O sistema que integra os registros do comércio exterior","Um imposto federal cobrado sobre todas as exportações","Um tribunal administrativo aduaneiro","Uma zona franca"],"explicacao":"Registra importações e exportações."},{"id":7065,"materia":"adua","nivel":3,"enunciado":"O drawback é um regime que:","opcoes":["Desonera insumos importados usados em produtos exportados","Proíbe a importação de insumos usados pela indústria nacional","Aumenta o imposto sobre as exportações","Isenta qualquer compra no exterior"],"explicacao":"Estimula as exportações."},{"id":7066,"materia":"adua","nivel":3,"enunciado":"Na admissão temporária, os bens entram no país:","opcoes":["Por prazo determinado, com suspensão de tributos","Para ficar para sempre, sem pagar tributos","Só para revenda no mercado interno","Sem nenhum controle"],"explicacao":"Exemplo: equipamentos para uma feira."},{"id":7067,"materia":"adua","nivel":4,"enunciado":"No despacho de importação, o canal cinza indica:","opcoes":["Exame documental e físico, com procedimento especial","Liberação automática da carga, sem nenhum exame","Só conferência dos documentos apresentados","Mercadoria de baixo valor"],"explicacao":"Investiga, por exemplo, subfaturamento."},{"id":7068,"materia":"adua","nivel":4,"enunciado":"O principal método para definir o valor aduaneiro, segundo o Acordo de Valoração da OMC, é o:","opcoes":["Valor de transação","Valor de mercado no Brasil","Valor arbitrado pelo fiscal","Preço do frete"],"explicacao":"É o preço efetivamente pago ou a pagar."},{"id":7069,"materia":"adua","nivel":4,"enunciado":"A pena de perdimento consiste em:","opcoes":["Perda da mercadoria em favor da União, por infração grave","Multa de 1% do valor declarado da mercadoria importada","Advertência por escrito ao importador","Devolução da mercadoria ao exterior"],"explicacao":"Aplica-se, por exemplo, a mercadoria abandonada ou com documentos falsos."},{"id":7070,"materia":"eco","nivel":1,"enunciado":"A taxa básica de juros (Selic) é definida pelo:","opcoes":["Copom, do Banco Central","Congresso Nacional","Ministério da Fazenda","Supremo Tribunal Federal"],"explicacao":"O Comitê de Política Monetária se reúne a cada 45 dias."},{"id":7071,"materia":"eco","nivel":2,"enunciado":"Quando o Banco Central aumenta a Selic, o objetivo costuma ser:","opcoes":["Conter a inflação, encarecendo o crédito","Aumentar o consumo das famílias imediatamente","Baixar os juros cobrados pelos bancos","Imprimir mais dinheiro"],"explicacao":"Juros altos esfriam a demanda."},{"id":7072,"materia":"eco","nivel":1,"enunciado":"O PIB mede:","opcoes":["O valor dos bens e serviços finais produzidos","Só o valor das exportações do país no ano","A riqueza acumulada pelos mais ricos","Os impostos arrecadados"],"explicacao":"Produto Interno Bruto."},{"id":7073,"materia":"eco","nivel":0,"enunciado":"Se a procura por um produto aumenta e a oferta continua igual, o preço tende a:","opcoes":["Subir","Cair","Ficar igual","Zerar"],"explicacao":"Lei da oferta e da demanda."},{"id":7074,"materia":"eco","nivel":1,"enunciado":"Quando só uma empresa vende um produto sem substitutos próximos, há:","opcoes":["Monopólio","Concorrência perfeita","Oligopólio","Monopsônio"],"explicacao":"No monopsônio, há um só comprador."},{"id":7075,"materia":"eco","nivel":2,"enunciado":"A política fiscal trata principalmente de:","opcoes":["Gastos e arrecadação do governo","Taxa de juros e oferta de moeda","Câmbio fixo","Comércio entre empresas"],"explicacao":"A política monetária cuida dos juros e da moeda."},{"id":7076,"materia":"eco","nivel":3,"enunciado":"Há déficit primário quando:","opcoes":["As despesas superam as receitas, sem contar os juros","O país exporta mais do que importa no mesmo ano","A inflação fica abaixo do centro da meta","O PIB cresce"],"explicacao":"Com os juros, fala-se em resultado nominal."},{"id":7077,"materia":"eco","nivel":4,"enunciado":"A Lei Complementar 200/2023 criou o novo regime fiscal, conhecido como arcabouço fiscal, que substituiu:","opcoes":["O teto de gastos","A Lei de Responsabilidade Fiscal","O Plano Real","A Lei 4.320/1964"],"explicacao":"Liga o crescimento das despesas ao das receitas."},{"id":7078,"materia":"aud","nivel":1,"enunciado":"A auditoria independente (externa) é feita por:","opcoes":["Auditor sem vínculo com a empresa auditada","Funcionário do setor financeiro da própria empresa","Sócio majoritário","Cliente da empresa"],"explicacao":"A independência dá credibilidade à opinião."},{"id":7079,"materia":"aud","nivel":1,"enunciado":"A auditoria interna:","opcoes":["Faz parte da organização e avalia seus controles","É sempre feita pelos auditores do Tribunal de Contas","Só existe em órgãos públicos federais","Substitui a contabilidade"],"explicacao":"Apoia a gestão."},{"id":7080,"materia":"aud","nivel":1,"enunciado":"A diferença entre fraude e erro, para a auditoria, é que a fraude:","opcoes":["É intencional","É sempre de pequeno valor","Nunca afeta as demonstrações","É culpa do auditor"],"explicacao":"O erro é involuntário."},{"id":7081,"materia":"aud","nivel":2,"enunciado":"A opinião sem ressalva (\"limpa\") indica que as demonstrações:","opcoes":["Estão adequadas em todos os aspectos relevantes","Têm erros graves e generalizados","Não puderam ser auditadas por falta de dados","Foram rejeitadas"],"explicacao":"Conforme a estrutura de relatório aplicável."},{"id":7082,"materia":"aud","nivel":3,"enunciado":"Quando o auditor não consegue obter evidência suficiente e os possíveis efeitos são generalizados, ele:","opcoes":["Se abstém de emitir opinião","Emite opinião sem ressalva","Emite opinião adversa","Assina sem examinar"],"explicacao":"NBC TA 705."},{"id":7083,"materia":"aud","nivel":3,"enunciado":"Pedir a um banco ou cliente que confirme diretamente ao auditor um saldo é a técnica de:","opcoes":["Confirmação externa (circularização)","Recálculo de saldos das contas","Indagação a funcionários","Observação"],"explicacao":"É uma evidência obtida de fonte independente."},{"id":7084,"materia":"aud","nivel":2,"enunciado":"Acompanhar a contagem dos estoques feita pela empresa é a técnica de:","opcoes":["Observação (inspeção física)","Circularização de clientes","Confirmação bancária","Revisão analítica"],"explicacao":"Confirma a existência dos itens."},{"id":7085,"materia":"aud","nivel":4,"enunciado":"O risco de auditoria é composto pelo risco de distorção relevante (inerente e de controle) e pelo risco de:","opcoes":["Detecção","Mercado","Câmbio","Liquidez"],"explicacao":"O auditor controla o risco de detecção com seus procedimentos."},{"id":7086,"materia":"aud","nivel":3,"enunciado":"O teste de controle serve para avaliar:","opcoes":["Se os controles internos funcionam de forma eficaz","O valor de mercado das ações da empresa na bolsa","A taxa de juros dos empréstimos","O lucro futuro"],"explicacao":"Os testes substantivos buscam distorções nos saldos."},{"id":7087,"materia":"dados","nivel":1,"enunciado":"Numa tabela de dados, cada linha costuma representar:","opcoes":["Um registro, como uma nota fiscal","Um tipo de gráfico de barras","Um programa de computador","Uma senha"],"explicacao":"As colunas são os atributos."},{"id":7088,"materia":"dados","nivel":2,"enunciado":"Numa cidade com um bilionário, a medida que melhor representa a renda típica dos moradores é a:","opcoes":["Mediana","Média","Soma total","Maior valor"],"explicacao":"A mediana não é puxada por valores extremos."},{"id":7089,"materia":"dados","nivel":1,"enunciado":"Para mostrar a arrecadação mês a mês ao longo de um ano, o gráfico mais adequado é o de:","opcoes":["Linhas","Pizza","Dispersão sem eixo de tempo","Mapa"],"explicacao":"Mostra a evolução no tempo."},{"id":7090,"materia":"dados","nivel":0,"enunciado":"Para mostrar as partes de um todo, como a divisão de um orçamento, usa-se com frequência o gráfico de:","opcoes":["Setores (pizza)","Linhas","Dispersão","Histograma de frequência"],"explicacao":"Funciona bem com poucas categorias."},{"id":7091,"materia":"dados","nivel":2,"enunciado":"Duas variáveis sobem juntas. Pode-se concluir que uma causa a outra?","opcoes":["Não; correlação não implica causalidade","Sim, sempre que as duas subirem juntas no gráfico","Sim, se forem números grandes","Só se forem em reais"],"explicacao":"Pode haver um terceiro fator."},{"id":7092,"materia":"dados","nivel":1,"enunciado":"Num conjunto de dados, um outlier é:","opcoes":["Um valor muito distante dos demais","A média de todos os valores","O valor mais frequente da lista","Uma coluna vazia"],"explicacao":"Pode ser erro de digitação ou um caso real fora do padrão."},{"id":7093,"materia":"dados","nivel":1,"enunciado":"Um arquivo CSV é:","opcoes":["Texto com valores separados por vírgula","Uma imagem em alta resolução, com camadas","Um vídeo compactado","Um programa executável"],"explicacao":"Abre em planilhas e em quase todo sistema."},{"id":7094,"materia":"dados","nivel":3,"enunciado":"No SQL, a cláusula usada para filtrar as linhas de uma consulta é:","opcoes":["WHERE","ORDER BY","SELECT","FROM"],"explicacao":"ORDER BY ordena; SELECT escolhe as colunas."},{"id":7095,"materia":"dados","nivel":2,"enunciado":"Num painel de gestão, um KPI é:","opcoes":["Um indicador-chave de desempenho","Um tipo de vírus de computador","Um relatório impresso em papel","Uma senha de acesso"],"explicacao":"Exemplo: tempo médio de atendimento."},{"id":7096,"materia":"dados","nivel":3,"enunciado":"Pela LGPD, é exemplo de dado pessoal sensível:","opcoes":["Informação de saúde","Nome da empresa","Endereço comercial","Número da nota fiscal"],"explicacao":"Também origem racial, religião, biometria, entre outros."},{"id":7097,"materia":"prev","nivel":0,"enunciado":"O INSS é:","opcoes":["A autarquia que paga os benefícios do regime geral","Um banco privado que administra a poupança dos trabalhadores","Um imposto estadual sobre salários","Um plano de saúde"],"explicacao":"Instituto Nacional do Seguro Social."},{"id":7098,"materia":"prev","nivel":1,"enunciado":"O salário-maternidade é pago, em regra, por:","opcoes":["120 dias","30 dias","60 dias","1 ano"],"explicacao":"Art. 71 da Lei 8.213/1991."},{"id":7099,"materia":"prev","nivel":1,"enunciado":"A pensão por morte é paga:","opcoes":["Aos dependentes do segurado que faleceu","Ao próprio segurado","A qualquer pessoa da família, sem regras","Só ao empregador"],"explicacao":"Cônjuge, filhos e outros dependentes previstos em lei."},{"id":7100,"materia":"prev","nivel":2,"enunciado":"O antigo auxílio-doença passou a se chamar:","opcoes":["Auxílio por incapacidade temporária","Benefício de prestação continuada","Seguro-desemprego","Aposentadoria especial"],"explicacao":"Nome adotado após a EC 103/2019."},{"id":7101,"materia":"prev","nivel":2,"enunciado":"Um eletricista autônomo que presta serviços por conta própria é segurado:","opcoes":["Contribuinte individual","Empregado","Segurado especial","Segurado facultativo"],"explicacao":"Ele mesmo recolhe sua contribuição."},{"id":7102,"materia":"prev","nivel":3,"enunciado":"O Benefício de Prestação Continuada (BPC/LOAS):","opcoes":["Paga 1 salário mínimo a idoso ou PcD de baixa renda","É uma aposentadoria com direito a 13º e a pensão por morte","Exige 15 anos de contribuição ao INSS","Só é pago a servidores públicos"],"explicacao":"É assistencial, sem exigência de contribuição."},{"id":7103,"materia":"trib","nivel":0,"enunciado":"O imposto sobre a propriedade territorial rural (ITR) é de competência:","opcoes":["Da União","Dos municípios","Dos estados","Do Incra"],"explicacao":"Os municípios podem optar por fiscalizá-lo e ficar com a arrecadação."},{"id":7104,"materia":"trib","nivel":1,"enunciado":"O IOF incide sobre operações de:","opcoes":["Crédito, câmbio, seguro e títulos","Venda de mercadorias no varejo","Serviços de beleza e estética","Propriedade de imóveis"],"explicacao":"É imposto federal com função regulatória."},{"id":7105,"materia":"trib","nivel":2,"enunciado":"Pelo CTN, o responsável tributário é aquele que:","opcoes":["Não pratica o fato gerador, mas a lei o obriga","Pratica o fato gerador diretamente e por conta própria","Fiscaliza o pagamento do tributo","Cria o tributo por lei"],"explicacao":"O contribuinte é quem tem relação direta com o fato gerador."},{"id":7106,"materia":"trib","nivel":2,"enunciado":"O princípio da capacidade contributiva determina que os impostos sejam:","opcoes":["Graduados conforme a capacidade econômica","Iguais para todos, num valor fixo","Cobrados só dos mais pobres","Definidos pelo próprio contribuinte"],"explicacao":"Art. 145, § 1º, da Constituição."},{"id":7107,"materia":"trib","nivel":3,"enunciado":"Compensação, transação e remissão são formas de:","opcoes":["Extinção do crédito tributário","Suspensão do crédito tributário","Exclusão do crédito tributário","Constituição do crédito"],"explicacao":"Art. 156 do CTN."},{"id":7108,"materia":"trib","nivel":4,"enunciado":"Na substituição tributária \"para frente\", o tributo é recolhido:","opcoes":["Antes, com base num fato gerador futuro presumido","Só depois da venda efetiva ao consumidor final","Pelo próprio consumidor, direto ao fisco","Nunca, por ser isento"],"explicacao":"Art. 150, § 7º, da Constituição."},{"id":7109,"materia":"trib","nivel":1,"enunciado":"A nota fiscal eletrônica tem validade jurídica garantida por:","opcoes":["Assinatura digital e autorização do fisco","Carimbo e rubrica do contador responsável","Assinatura à mão do cliente","Cópia em papel autenticada"],"explicacao":"O DANFE é só uma representação impressa."},{"id":7110,"materia":"afo","nivel":1,"enunciado":"Os tributos arrecadados pelo governo são exemplo de receita:","opcoes":["Corrente","De capital","Extraorçamentária","Patrimonial apenas"],"explicacao":"Receitas de capital vêm de empréstimos e venda de bens, entre outras."},{"id":7111,"materia":"afo","nivel":2,"enunciado":"Pelo princípio da universalidade, a LOA deve conter:","opcoes":["Todas as receitas e despesas","Só as despesas com pessoal","Só os investimentos","Só as receitas de impostos"],"explicacao":"Art. 165, § 5º, da Constituição."},{"id":7112,"materia":"afo","nivel":0,"enunciado":"Na União, quem elabora o projeto de lei do orçamento é o:","opcoes":["Poder Executivo","Supremo Tribunal Federal","Tribunal de Contas","Banco Central"],"explicacao":"O Congresso discute e aprova."},{"id":7113,"materia":"afo","nivel":0,"enunciado":"Na União, quem aprova a lei orçamentária é o:","opcoes":["Congresso Nacional","Presidente sozinho","Ministério da Fazenda","STF"],"explicacao":"Depois, o presidente sanciona."},{"id":7114,"materia":"afo","nivel":1,"enunciado":"A LRF exige que as contas públicas sejam divulgadas:","opcoes":["Também em meios eletrônicos de acesso público","Só em papel, no diário oficial do respectivo ente","Só para os servidores do órgão","Só depois de 10 anos"],"explicacao":"Base dos portais da transparência."},{"id":7115,"materia":"cont","nivel":0,"enunciado":"O capital investido pelos sócios fica registrado no:","opcoes":["Patrimônio líquido","Ativo circulante","Passivo circulante","Imobilizado"],"explicacao":"Conta capital social."},{"id":7116,"materia":"cont","nivel":0,"enunciado":"O caminhão usado pela empresa nas entregas é um ativo:","opcoes":["Imobilizado","Circulante","Intangível","Financeiro"],"explicacao":"Bem tangível usado nas atividades por mais de um ano."},{"id":7117,"materia":"cont","nivel":1,"enunciado":"Uma marca registrada comprada pela empresa é um ativo:","opcoes":["Intangível","Imobilizado","Circulante","Financeiro"],"explicacao":"Não tem existência física."},{"id":7118,"materia":"cont","nivel":2,"enunciado":"Comprar mercadorias a prazo faz:","opcoes":["Aumentar o estoque e os fornecedores a pagar","Diminuir o caixa e o estoque ao mesmo tempo","Aumentar o patrimônio líquido","Diminuir o passivo"],"explicacao":"Não há saída de dinheiro na hora."},{"id":7119,"materia":"cont","nivel":2,"enunciado":"Pagar à vista a conta de luz da empresa faz:","opcoes":["Diminuir o caixa e o resultado do período","Aumentar o ativo circulante da empresa","Aumentar o passivo com fornecedores","Não muda nada"],"explicacao":"A despesa reduz o resultado."},{"id":7120,"materia":"adua","nivel":3,"enunciado":"O Mercosul, por ter tarifa externa comum mas com muitas exceções, é considerado:","opcoes":["Uma união aduaneira imperfeita","Um mercado comum completo","Uma simples zona de preferência","Uma união monetária"],"explicacao":"Ainda não tem livre circulação plena de fatores."},{"id":7121,"materia":"adua","nivel":3,"enunciado":"A Tarifa Externa Comum (TEC) é aplicada pelo Mercosul:","opcoes":["Às importações vindas de fora do bloco","Ao comércio entre os países do bloco","Só às exportações","Só a serviços"],"explicacao":"Busca uniformizar o tratamento externo."},{"id":7122,"materia":"adua","nivel":4,"enunciado":"Pela Lei 14.902/2024, compras internacionais de até US$ 50 pelo Remessa Conforme pagam Imposto de Importação de:","opcoes":["20%","60%","0%","100%"],"explicacao":"Ficou conhecida como \"taxa das blusinhas\"."},{"id":7123,"materia":"eco","nivel":3,"enunciado":"A taxa de desemprego no Brasil é medida pelo IBGE por meio da:","opcoes":["PNAD Contínua","Pesquisa de Orçamento Familiar","Relação Anual de Informações Sociais","Prova Brasil"],"explicacao":"Pesquisa domiciliar trimestral."},{"id":7124,"materia":"eco","nivel":1,"enunciado":"Quando poucas empresas dominam um mercado, como na telefonia, há:","opcoes":["Oligopólio","Monopólio","Concorrência perfeita","Escambo"],"explicacao":"As empresas acompanham as decisões umas das outras."},{"id":7125,"materia":"eco","nivel":3,"enunciado":"No câmbio flutuante adotado pelo Brasil:","opcoes":["O mercado define a cotação, e o BC intervém às vezes","O governo fixa o valor do dólar por decreto todo mês","A moeda oficial do país passa a ser o dólar","Não existe comércio exterior"],"explicacao":"Adotado desde 1999."},{"id":7126,"materia":"eco","nivel":1,"enunciado":"A balança comercial é superavitária quando:","opcoes":["As exportações superam as importações","As importações superam as exportações","O governo gasta menos","A inflação cai"],"explicacao":"É parte do balanço de pagamentos."},{"id":7127,"materia":"eco","nivel":1,"enunciado":"A queda generalizada dos preços chama-se:","opcoes":["Deflação","Inflação","Estagflação","Recessão"],"explicacao":"Pode indicar economia desaquecida."},{"id":7128,"materia":"aud","nivel":2,"enunciado":"Os papéis de trabalho do auditor são:","opcoes":["A documentação dos procedimentos e evidências","As demonstrações contábeis da empresa","Os contratos de trabalho dos funcionários","As notas fiscais de venda"],"explicacao":"Sustentam a opinião emitida."},{"id":7129,"materia":"aud","nivel":3,"enunciado":"Na auditoria, a materialidade (relevância) é:","opcoes":["O valor a partir do qual uma distorção influencia decisões","A quantidade de documentos analisados durante o trabalho","O tamanho físico das instalações da empresa","O salário do auditor"],"explicacao":"Orienta o planejamento e a avaliação dos achados."},{"id":7130,"materia":"aud","nivel":3,"enunciado":"A postura do auditor de questionar e avaliar criticamente as evidências chama-se:","opcoes":["Ceticismo profissional","Independência financeira","Sigilo profissional","Julgamento sumário"],"explicacao":"NBC TA 200."},{"id":7131,"materia":"aud","nivel":1,"enunciado":"No controle externo da União, o Congresso Nacional é auxiliado pelo:","opcoes":["Tribunal de Contas da União","Banco Central do Brasil","Ministério da Fazenda","STF"],"explicacao":"Art. 71 da Constituição."},{"id":7132,"materia":"dados","nivel":0,"enunciado":"Numa planilha, o recurso filtro serve para:","opcoes":["Mostrar só as linhas que atendem a um critério","Apagar de uma vez a planilha inteira e seus dados","Trocar a cor da fonte das células","Imprimir em PDF"],"explicacao":"Os dados ocultos não são apagados."},{"id":7133,"materia":"dados","nivel":1,"enunciado":"Para comparar a arrecadação de cinco municípios num mesmo ano, o gráfico mais adequado é o de:","opcoes":["Barras","Linhas","Pizza com 50 fatias","Dispersão"],"explicacao":"Barras comparam categorias."},{"id":7134,"materia":"dados","nivel":1,"enunciado":"A diferença entre dado e informação é que a informação:","opcoes":["É o dado organizado e com significado","É sempre um número inteiro","É o dado bruto, sem tratamento","Não pode ser armazenada"],"explicacao":"Ex.: \"37\" é dado; \"37 °C de febre\" é informação."},{"id":7135,"materia":"prev","nivel":0,"enunciado":"Contribuem para o INSS, em regra:","opcoes":["Os trabalhadores e os empregadores","Só os aposentados e pensionistas","Só o governo federal","Só os desempregados"],"explicacao":"O financiamento da seguridade é diversificado."},{"id":7136,"materia":"prev","nivel":2,"enunciado":"O abono anual pago aos aposentados e pensionistas do INSS equivale ao:","opcoes":["13º salário","Salário-família","Seguro-desemprego","PIS"],"explicacao":"Art. 40 da Lei 8.213/1991."},{"id":7137,"materia":"dados","nivel":0,"enunciado":"Numa planilha, as multas de três dias foram 2, 4 e 9. A média diária é:","opcoes":["5","4","15","9"],"explicacao":"(2 + 4 + 9) ÷ 3."},{"id":7138,"materia":"eco","nivel":0,"enunciado":"Se o salário sobe 3% num ano em que a inflação foi de 6%, o poder de compra do trabalhador:","opcoes":["Cai","Sobe","Fica igual","Dobra"],"explicacao":"Os preços subiram mais que o salário."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('trib','afo','cont','adua','eco','aud','dados','prev') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
